const logPath = path.join(BASE_DIR, 'analytics', 'publish_log.jsonl');
if (!fs.existsSync(logPath)) return [];

const lines = fs.readFileSync(logPath, 'utf8').split('\n').filter(Boolean);
const cutoff = Date.now() - 30 * 24 * 3600 * 1000;
const videos = lines
  .map(l => { try { return JSON.parse(l); } catch (e) { return null; } })
  .filter(v => v && v.youtubeVideoId && new Date(v.publishedAt).getTime() >= cutoff);

return videos.map(v => ({ json: { ...v, BASE_DIR } }));

const video = $('Loop Over Videos').first().json;
const stats = ($('Get YouTube Video Stats').first().json.items || [])[0]?.statistics || {};
const report = $('Get YouTube Analytics Report').first().json;
const row = (report.rows || [])[0] || [];
const cols = (report.columnHeaders || []).map(c => c.name);

function col(name) {
  const i = cols.indexOf(name);
  return i >= 0 ? row[i] : null;
}

return [{
  json: {
    videoId: video.videoId,
    youtubeVideoId: video.youtubeVideoId,
    topic: video.topic,
    title: video.title,
    hashtags: video.hashtags,
