// Aggregates analytics_store.jsonl into learnings.json consumed by the main
// pipeline's 'Load Config & Learnings' node (Module 1).
const fs = require('fs');
const path = require('path');
const BASE_DIR = process.env.AI_SHORTS_BASE_DIR || '/Users/tuht1/ai-shorts-videos';
const storePath = path.join(BASE_DIR, 'analytics', 'analytics_store.jsonl');
if (!fs.existsSync(storePath)) return [{ json: { skipped: true } }];

const rows = fs.readFileSync(storePath, 'utf8').split('\n').filter(Boolean)
  .map(l => { try { return JSON.parse(l); } catch (e) { return null; } })
  .filter(Boolean);

// keep only the most recent pull per video
const latestByVideo = {};
for (const r of rows) latestByVideo[r.videoId] = r;
const latest = Object.values(latestByVideo);

function score(r) {
  // retention + shares/comments weighted higher than raw views (proxy for
  // 'people who WANT to finish watching', matching the stated priority)
  return (r.retentionPct || 0) * 2 + (r.shares || 0) * 3 + (r.comments || 0) * 2 + (r.likes || 0) * 0.5 + (r.views || 0) * 0.01;
}

const ranked = latest.slice().sort((a, b) => score(b) - score(a));
const topPerformingTopics = ranked.slice(0, 5).map(r => r.topic);
const topPerformingHooks = ranked.slice(0, 5).map(r => r.title);
const avoid = ranked.slice(-5).filter(r => score(r) < score(ranked[0]) * 0.2).map(r => r.topic);

const learnings = { topPerformingTopics, topPerformingHooks, avoid, updatedAt: new Date().toISOString() };
fs.writeFileSync(path.join(BASE_DIR, 'analytics', 'learnings.json'), JSON.stringify(learnings, null, 2));

return [{ json: learnings }];
